-- #80 규칙 버전과 개장 뒤 보충 (ADR-0093 decision 2 #172 items 6, 7, 14 and 15, decision 3 '#80 보충의
-- 형태', ADR-0101). Generated by `drizzle-kit generate`, then hand-edited where marked: this header
-- and the tail. The snapshot is as generated.
--
-- - market_rule_versions: every version of a market's rules — the full text of the version items
--   (the title, the rule items and the times: RULE_VERSION_ITEMS of @buddha/shared) as jsonb with
--   every item's key, the items changed from the version before (keys of that list), and from v2
--   on the supplement's reason, 정산 영향 검토, approved request and requester; who made it and
--   when. v1 is the open's (the content locked at the review, #172 item 6), each later one an
--   approved supplement's, made by an admin other than its requester (#172 item 15). Permanent
--   facts (N04 §5): no retention; buddha_app may INSERT and SELECT only, and a trigger refuses an
--   UPDATE or a DELETE whoever writes (below).
-- - markets.rule_version: the current version, 1 or more. Null before the open, and on every market
--   opened before #80 (D4: no backfill and no wipe — such a market keeps no version and takes no
--   supplement), so no CHECK ties it to a status. No foreign key to its version row, which
--   references the market: the open and the supplement approval write both in one transaction.
-- - The guard of a versioned market's rules (below): its version items, its market_sources rows and
--   rule_version change only in a transaction that names the market in the transaction-local
--   setting `buddha.rule_supplement` — the supplement approval's.
CREATE TABLE "market_rule_versions" (
	"market_id" uuid NOT NULL,
	"version" integer NOT NULL,
	"content" jsonb NOT NULL,
	"changed_items" text[] DEFAULT '{}'::text[] NOT NULL,
	"reason" text,
	"settlement_impact" text,
	"approval_id" uuid,
	"requested_by" text,
	"created_by" text,
	"created_at" timestamp (3) with time zone NOT NULL,
	CONSTRAINT "market_rule_versions_market_id_version_pk" PRIMARY KEY("market_id","version"),
	CONSTRAINT "market_rule_versions_approval_id_unique" UNIQUE("approval_id"),
	CONSTRAINT "market_rule_versions_version_check" CHECK ("market_rule_versions"."version" >= 1),
	CONSTRAINT "market_rule_versions_supplement_check" CHECK (("market_rule_versions"."version" = 1) = ("market_rule_versions"."approval_id" IS NULL) AND ("market_rule_versions"."version" = 1) = ("market_rule_versions"."requested_by" IS NULL) AND ("market_rule_versions"."version" = 1) = ("market_rule_versions"."reason" IS NULL) AND ("market_rule_versions"."version" = 1) = ("market_rule_versions"."settlement_impact" IS NULL) AND ("market_rule_versions"."version" = 1) = (cardinality("market_rule_versions"."changed_items") = 0) AND ("market_rule_versions"."version" = 1 OR ("market_rule_versions"."created_by" IS NOT NULL AND "market_rule_versions"."created_by" <> "market_rule_versions"."requested_by"))),
	CONSTRAINT "market_rule_versions_reasons_check" CHECK (btrim("market_rule_versions"."reason") IS DISTINCT FROM '' AND btrim("market_rule_versions"."settlement_impact") IS DISTINCT FROM ''),
	CONSTRAINT "market_rule_versions_changed_items_check" CHECK ("market_rule_versions"."changed_items" <@ ARRAY['title', 'description', 'yesCondition', 'noCondition', 'eventDeadline', 'primarySource', 'fallbackSources', 'fallbackCondition', 'longDelayDays', 'delayHandling', 'scheduledOpenAt', 'closeAt', 'scheduledAnnouncementAt', 'scheduledJudgementAt', 'judgementTimeZone']::text[]),
	CONSTRAINT "market_rule_versions_content_check" CHECK (jsonb_typeof("market_rule_versions"."content") = 'object' AND "market_rule_versions"."content" ?& ARRAY['title', 'description', 'yesCondition', 'noCondition', 'eventDeadline', 'primarySource', 'fallbackSources', 'fallbackCondition', 'longDelayDays', 'delayHandling', 'scheduledOpenAt', 'closeAt', 'scheduledAnnouncementAt', 'scheduledJudgementAt', 'judgementTimeZone']::text[])
);
--> statement-breakpoint
