-- Hand-edited: a rule version is a permanent fact (N04 §5), never rewritten or removed. buddha_app
-- keeps SELECT/INSERT of the default privileges in docker/postgres/init/01-roles.sql and loses
-- UPDATE and DELETE.
REVOKE UPDATE, DELETE ON TABLE "market_rule_versions" FROM buddha_app;--> statement-breakpoint
-- Hand-edited: nor does any other role (the migration role, a script): the public history shows
-- each version and the judgement follows the last (#172 item 7), so a version stays as it was
-- made, whoever writes. TRUNCATE fires no row trigger: the wipe (wipe.ts) still empties the table.
CREATE FUNCTION market_rule_versions_keep_record() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'rule version % of market % is a permanent record and takes no %', OLD.version,
    OLD.market_id, TG_OP
    USING ERRCODE = 'integrity_constraint_violation';
END;
$$;--> statement-breakpoint
CREATE TRIGGER market_rule_versions_keep_record
  BEFORE UPDATE OR DELETE ON "market_rule_versions"
  FOR EACH ROW EXECUTE FUNCTION market_rule_versions_keep_record();--> statement-breakpoint
-- Hand-edited: the guard of a versioned market's rules (#80: '보충 외 경로로 규칙 버전에 든 항목을
-- 고치는 일을 막는다'). Once a market has a rule version, its version items and rule_version change
-- only in a transaction that names the market in the setting `buddha.rule_supplement`
-- (set_config(…, true), transaction-local: `allowRuleSupplement` in packages/db) — the supplement
-- approval, which writes the new text, the next version and its row together. Any other write is
-- refused whoever writes: an API path that forgot the rule, a script. The same value again is no
-- change. A market with no version — a draft up to SCHEDULED, or one opened before #80 (D4) — is
-- not held, and the open gives it its first (null → 1). BEFORE UPDATE OF those columns, so a write
-- of the others (a transition other than the open, a fill's statistics, the settlement) never calls
-- it — the open's sets rule_version and passes as unversioned; markets has no generated column, so
-- a BEFORE row trigger costs its UPDATEs no stronger lock (0044's note).
CREATE FUNCTION markets_keep_rule_version() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.rule_version IS NOT NULL
     AND (NEW.title, NEW.description, NEW.yes_condition, NEW.no_condition, NEW.event_deadline,
          NEW.fallback_condition, NEW.long_delay_days, NEW.delay_handling, NEW.scheduled_open_at,
          NEW.close_at, NEW.scheduled_announcement_at, NEW.scheduled_judgement_at,
          NEW.judgement_time_zone, NEW.rule_version)
         IS DISTINCT FROM
         (OLD.title, OLD.description, OLD.yes_condition, OLD.no_condition, OLD.event_deadline,
          OLD.fallback_condition, OLD.long_delay_days, OLD.delay_handling, OLD.scheduled_open_at,
          OLD.close_at, OLD.scheduled_announcement_at, OLD.scheduled_judgement_at,
          OLD.judgement_time_zone, OLD.rule_version)
     AND current_setting('buddha.rule_supplement', true) IS DISTINCT FROM OLD.id::text THEN
    RAISE EXCEPTION
      'market % is at rule version %: its rules change by an approved supplement only',
      OLD.id, OLD.rule_version
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER markets_keep_rule_version
  BEFORE UPDATE OF "title", "description", "yes_condition", "no_condition", "event_deadline",
    "fallback_condition", "long_delay_days", "delay_handling", "scheduled_open_at", "close_at",
    "scheduled_announcement_at", "scheduled_judgement_at", "judgement_time_zone", "rule_version"
  ON "markets"
  FOR EACH ROW EXECUTE FUNCTION markets_keep_rule_version();--> statement-breakpoint
-- Hand-edited: and its sources, which are rows of their own (a write deletes and inserts them): an
-- INSERT, UPDATE or DELETE of a market_sources row of a market with a rule version needs the same
-- setting naming that market. The market is read FOR SHARE, so a write racing the open or an
-- approval waits for its COMMIT and then reads the version it wrote (READ COMMITTED reads the
-- newest row after the wait), never the one before. An UPDATE that changes nothing is no change.
CREATE FUNCTION market_sources_keep_rule_version() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  targets uuid[];
  target uuid;
  held integer;
BEGIN
  IF TG_OP = 'INSERT' THEN
    targets := ARRAY[NEW.market_id];
  ELSIF TG_OP = 'DELETE' THEN
    targets := ARRAY[OLD.market_id];
  ELSIF NEW IS NOT DISTINCT FROM OLD THEN
    RETURN NEW;
  ELSE
    targets := ARRAY[OLD.market_id, NEW.market_id];
  END IF;
  FOREACH target IN ARRAY targets LOOP
    SELECT rule_version INTO held FROM markets WHERE id = target FOR SHARE;
    IF held IS NOT NULL
       AND current_setting('buddha.rule_supplement', true) IS DISTINCT FROM target::text THEN
      RAISE EXCEPTION
        'market % is at rule version %: its sources change by an approved supplement only',
        target, held
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END LOOP;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER market_sources_keep_rule_version
  BEFORE INSERT OR UPDATE OR DELETE ON "market_sources"
  FOR EACH ROW EXECUTE FUNCTION market_sources_keep_rule_version();
